let fullText = msg.originalMessage.text || "";
let parts = fullText.trim().split(" ");
let commandTyped = parts[0].replace("/", "");
let targetDevice = "";
let mqttMsg = null;
let errorMsg = null;

if (commandTyped === "do") {
    if (parts.length < 4) {
        errorMsg = {
            payload: {
                type: 'message',
                chatId: msg.payload.chatId,
                content: `⚠️ Please specify state, channel, and machine name.\nExample: /do on 1 Machine1`
            }
        };
        return [null, errorMsg, null];
    }
    let state = parts[1].toLowerCase();
    let target = parts[2];
    targetDevice = parts[3];

    mqttMsg = {
        topic: "esp32/" + targetDevice + "/command",
        payload: JSON.stringify({
            cmd: "do",
            state: state,
            target: parseInt(target),
            chatId: msg.payload.chatId
        })
    };
} else {
    if (parts.length < 2 || parts[1] === "") {
        errorMsg = {
            payload: {
                type: 'message',
                chatId: msg.payload.chatId,
                content: `⚠️ Please specify a machine name.\nExample: /${commandTyped} Machine1`
            }
        };
        return [null, errorMsg, null];
    }
    targetDevice = parts[1];

    mqttMsg = {
        topic: "esp32/" + targetDevice + "/command",
        payload: JSON.stringify({
            cmd: commandTyped,
            chatId: msg.payload.chatId
        })
    };
}

// --- SMART TIMEOUT LOGIC ---
let chatId = msg.payload.chatId;
let timeouts = flow.get("timeouts") || {};

if (timeouts[chatId]) {
    clearTimeout(timeouts[chatId]);
}

timeouts[chatId] = setTimeout(() => {
    node.send([null, null, {
        payload: {
            type: "message",
            chatId: chatId,
            content: `⚠️ No device named '${targetDevice}' detected, or the device is offline.`
        }
    }]);

    let t = flow.get("timeouts") || {};
    delete t[chatId];
    flow.set("timeouts", t);
}, 3000); // 3 seconds timeout

flow.set("timeouts", timeouts);

return [mqttMsg, null, null];

let cache = flow.get("esp32_cache") || { devices: {}, tg: {}, auto: {} };
let parts = msg.topic.split("/");
let device = parts[1];
let type = parts.slice(2).join("/");
let val = msg.payload.toString();

let selectedDevice = flow.get("selectedDevice"); // The Config Dropdown

let msgDropdownDO = null;
let msgDropdownConfig = null;
let msgTg = null;
let msgAuto = null;

if (type === "status") {
    if (val === "online") {
        cache.devices[device] = true;
    } else {
        delete cache.devices[device];
    }

    let activeMachines = Object.keys(cache.devices);

    // Output 1: Dropdown DO & DI (Only active machines)
    msgDropdownDO = { options: activeMachines };

    // Output 2: Dropdown Config (Active machines + ALL MACHINE)
    let configMachines = [...activeMachines];
    configMachines.unshift("ALL MACHINE");
    msgDropdownConfig = { options: configMachines };

} else if (type === "telegram/enabled") {
    cache.tg[device] = val;
    if (device === selectedDevice) msgTg = { payload: val };
} else if (type === "update/auto/status") {
    cache.auto[device] = val;
    if (device === selectedDevice) msgAuto = { payload: val };
}

flow.set("esp32_cache", cache);

// Note we are returning 4 outputs now!
return [msgDropdownDO, msgDropdownConfig, msgTg, msgAuto];

let selectedDevice = msg.payload;
flow.set("selectedDevice", selectedDevice);

let cache = flow.get("esp32_cache") || { tg: {}, auto: {} };
let msgTg = null;
let msgAuto = null;

if (selectedDevice === "ALL MACHINE") {
    // Visual default for switches when ALL is selected
    msgTg = { payload: "0" };
    msgAuto = { payload: "0" };
} else {
    msgTg = { payload: cache.tg[selectedDevice] || "0" };
    msgAuto = { payload: cache.auto[selectedDevice] || "0" };
}

return [msgTg, msgAuto];

let selectedDevice = flow.get("selectedDevice");
if (!selectedDevice) return null;

if (selectedDevice === "ALL MACHINE") {
    let cache = flow.get("esp32_cache") || { devices: {} };
    let msgs = [];
    for (let device in cache.devices) {
        msgs.push({
            topic: `esp32/${device}/telegram/enabled/set`,
            payload: msg.payload
        });
    }
    return [msgs]; // Broadcasts to all online devices sequentially
} else {
    msg.topic = `esp32/${selectedDevice}/telegram/enabled/set`;
    return msg;
}

let selectedDevice = flow.get("selectedDevice");
if (!selectedDevice) return null;

if (selectedDevice === "ALL MACHINE") {
    let cache = flow.get("esp32_cache") || { devices: {} };
    let msgs = [];
    for (let device in cache.devices) {
        msgs.push({
            topic: `esp32/${device}/update/auto/set`,
            payload: msg.payload
        });
    }
    return [msgs]; // Broadcasts to all online devices sequentially
} else {
    msg.topic = `esp32/${selectedDevice}/update/auto/set`;
    return msg;
}

let selectedDevice = flow.get("selectedDevice");
if (!selectedDevice) return null;

if (selectedDevice === "ALL MACHINE") {
    let cache = flow.get("esp32_cache") || { devices: {} };
    let msgs = [];
    for (let device in cache.devices) {
        msgs.push({
            topic: `esp32/${device}/ota_trigger`,
            payload: "1"
        });
    }
    return [msgs]; // Broadcasts to all online devices sequentially
} else {
    msg.topic = `esp32/${selectedDevice}/ota_trigger`;
    msg.payload = "1";
    return msg;
}

let selectedDevice = flow.get("selectedDevice");
if (!selectedDevice) return null;

// Convert "DI3" to 3
let sInt = parseInt(msg.payload.sensor.replace("DI", ""));
let jsonPayload = JSON.stringify({ sensor: sInt, count: msg.payload.count });

if (selectedDevice === "ALL MACHINE") {
    let cache = flow.get("esp32_cache") || { devices: {} };
    let msgs = [];
    for (let device in cache.devices) {
        msgs.push({
            topic: `esp32/${device}/triggercount/set`,
            payload: jsonPayload
        });
    }
    return [msgs];
} else {
    msg.topic = `esp32/${selectedDevice}/triggercount/set`;
    msg.payload = jsonPayload;
    return msg;
}

let selectedDevice = flow.get("selectedDevice");
if (!selectedDevice) return null;

// Convert "DI3" to 3
let sInt = parseInt(msg.payload.sensor.replace("DI", ""));
let jsonPayload = JSON.stringify({ sensor: sInt });

if (selectedDevice === "ALL MACHINE") {
    let cache = flow.get("esp32_cache") || { devices: {} };
    let msgs = [];
    for (let device in cache.devices) {
        msgs.push({
            topic: `esp32/${device}/triggercount/reset`,
            payload: jsonPayload
        });
    }
    return [msgs];
} else {
    msg.topic = `esp32/${selectedDevice}/triggercount/reset`;
    msg.payload = jsonPayload;
    return msg;
}

// 1. Parse the incoming JSON safely
let doc;
if (typeof msg.payload === "object") {
    doc = msg.payload;
} else {
    try {
        doc = JSON.parse(msg.payload.toString());
    } catch (e) {
        return null;
    }
}

// 2. Inject default Chat ID for spontaneous alerts (Boot, Reject, OTA)
if (!doc.chatId) {
    doc.chatId = "721886383"; // Your Admin Chat ID
}

let chatId = doc.chatId;

// 3. Clear any pending command timeouts (so your bot doesn't get stuck)
let timeouts = flow.get("timeouts") || {};
if (timeouts[chatId]) {
    clearTimeout(timeouts[chatId]);
    delete timeouts[chatId];
    flow.set("timeouts", timeouts);
}

// 4. Format the final Telegram message
let finalMessage = doc.message;
if (doc.device) {
    // I left the \n here so it matches your original style!
    finalMessage = `[${doc.device}]\n${doc.message}`;
}

msg.payload = {
    type: "message",
    chatId: chatId,
    content: finalMessage
};

return msg;

let cache = flow.get("esp32_cache") || { devices: {}, tg: {}, auto: {}, do: {}, di: {}, doTopics: {} };
let lockouts = flow.get("do_lockouts") || {};

let parts = msg.topic.split("/");
let device = parts[1];
let lastPart = parts[parts.length - 1];
let prevPart = parts.length > 2 ? parts[parts.length - 2] : "";

let selectedDeviceDO = flow.get("selectedDeviceDO");
let msgs = new Array(16).fill(null);

if (lastPart.startsWith("do")) {
    let doNum = parseInt(lastPart.replace("do", "")) - 1;
    if (doNum >= 0 && doNum < 8) {
        if (!cache.do[device]) cache.do[device] = {};
        cache.do[device][doNum] = msg.payload.toString();

        if (!cache.doTopics) cache.doTopics = {};
        if (!cache.doTopics[device]) cache.doTopics[device] = [];
        cache.doTopics[device][doNum] = msg.topic;

        let isLockedOut = false;
        if (lockouts[device] && lockouts[device][doNum] && (Date.now() - lockouts[device][doNum] < 1500)) {
            isLockedOut = true; 
        }

        if (!isLockedOut && device === selectedDeviceDO) {
            msgs[doNum] = { payload: msg.payload.toString() };
        }
    }
} else if (lastPart.startsWith("di") && prevPart === "count") {
    let diNum = parseInt(lastPart.replace("di", "")) - 1;
    if (diNum >= 0 && diNum < 8) {
        if (!cache.di[device]) cache.di[device] = {};
        cache.di[device][diNum] = msg.payload.toString();

        if (device === selectedDeviceDO) {
            msgs[8 + diNum] = { payload: msg.payload.toString() };
        }
    }
}
flow.set("esp32_cache", cache);
return msgs;

let selectedDeviceDO = msg.payload;
flow.set("selectedDeviceDO", selectedDeviceDO);

let cache = flow.get("esp32_cache") || { tg: {}, auto: {}, do: {}, di: {} };
if (!cache.do) cache.do = {};
if (!cache.di) cache.di = {};
let msgs = new Array(16).fill(null);

for (let i=0; i<8; i++) msgs[i] = { payload: (cache.do[selectedDeviceDO] && cache.do[selectedDeviceDO][i]) ? cache.do[selectedDeviceDO][i] : "0" };
for (let i=0; i<8; i++) msgs[8+i] = { payload: (cache.di[selectedDeviceDO] && cache.di[selectedDeviceDO][i]) ? cache.di[selectedDeviceDO][i] : "0" };

return msgs;

let selectedDeviceDO = flow.get("selectedDeviceDO");
if (!selectedDeviceDO) return null;

let doTopic = msg.topic;
let doNum = parseInt(doTopic.replace("do", "")) - 1;
let cache = flow.get("esp32_cache") || { devices: {}, do: {}, doTopics: {} };

// 1) INFINITE LOOP BREAKER
if (cache.do && cache.do[selectedDeviceDO]) {
    let currentESP32State = cache.do[selectedDeviceDO][doNum];
    if (currentESP32State === msg.payload.toString()) {
        return null;
    }
}

// ANTI-BOUNCE TIMESTAMP
let lockouts = flow.get("do_lockouts") || {};
if (!lockouts[selectedDeviceDO]) lockouts[selectedDeviceDO] = {};
lockouts[selectedDeviceDO][doNum] = Date.now();
flow.set("do_lockouts", lockouts);

// 2) SEND TO CUSTOM TOPICS
let targetTopic = `esp32/${selectedDeviceDO}/${doTopic}`;
if (cache.doTopics && cache.doTopics[selectedDeviceDO] && cache.doTopics[selectedDeviceDO][doNum]) {
    targetTopic = cache.doTopics[selectedDeviceDO][doNum];
}
msg.topic = targetTopic;
return msg;
